"use strict";(self.webpackChunkmcp_ai=self.webpackChunkmcp_ai||[]).push([[1894],{28453:(e,t,i)=>{i.d(t,{R:()=>o,x:()=>r});var a=i(96540);const s={},n=a.createContext(s);function o(e){const t=a.useContext(n);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:o(e.components),a.createElement(n.Provider,{value:t},e.children)}},37198:(e,t,i)=>{i.r(t),i.d(t,{assets:()=>l,contentTitle:()=>c,default:()=>h,faqJsonLd:()=>p,frontMatter:()=>r,metadata:()=>a,toc:()=>d});var a=i(49363),s=i(74848),n=i(28453),o=i(5260);const r={title:"MCP Elicitation Is a Symptom, Not a Strategy",description:"Why reaching for MCP elicitation usually means a tool's input contract has a gap; and how atomic, stateless APIs plus HAPI Workflows remove the need for it before it ever reaches the user.",authors:["adrian"],image:"/img/blog/mcp-elicitation-surfaces-issue-in-your-design.png",tags:["mcp","api-first","architecture","best-practices","arazzo"],keywords:["mcp elicitation","stateless api design","atomic api design","hapi workflows","arazzo","tool server design","mcp best practices"]},c=void 0,l={authorsImageUrls:[void 0]},p={"@context":"https://schema.org","@type":"FAQPage",mainEntity:[{"@type":"Question",name:"What is MCP elicitation?",acceptedAnswer:{"@type":"Answer",text:"MCP elicitation is a standardized feature (elicitation/create) that lets a server pause mid-task and ask the connected user for structured, schema-validated information through the client, instead of guessing a missing value or failing the request outright."}},{"@type":"Question",name:"Is MCP elicitation a bad practice?",acceptedAnswer:{"@type":"Answer",text:"No, but it's easy to overuse. Elicitation is the right tool for confirming a destructive action or asking for something only the user can know. It's the wrong tool for filling in a required field your API already knows is required, or for chaining together a multi-step process \u2014 both of those are design problems elicitation just papers over."}},{"@type":"Question",name:"How do I reduce the need for elicitation in my MCP tools?",acceptedAnswer:{"@type":"Answer",text:"Design each API operation to be atomic and explicit about its required parameters in the OpenAPI spec, so an agent can see what's required before it calls the tool instead of finding out mid-call. For processes that genuinely need multiple steps, define the sequence explicitly with HAPI Workflows (Arazzo) instead of letting the model improvise it through back-and-forth elicitation."}},{"@type":"Question",name:"What's the difference between elicitation and a multi-step workflow?",acceptedAnswer:{"@type":"Answer",text:"Elicitation asks a human for one flat, primitive value mid-call, at runtime, on demand. A workflow defines the dependency between steps \u2014 'this step's input comes from that step's output' \u2014 as an explicit, deterministic sequence the server executes, with no back-and-forth with the user needed to figure out what comes next."}},{"@type":"Question",name:"Can HAPI Workflows replace MCP elicitation for multi-step processes?",acceptedAnswer:{"@type":"Answer",text:"For the class of elicitation that exists only to chain calls together \u2014 'what's the ID from the last step?' \u2014 yes. HAPI Workflows, built on the Arazzo specification, let you define that dependency once as data, so the sequence runs deterministically instead of relying on the model to ask and remember it correctly every time."}},{"@type":"Question",name:"What data can I request through MCP elicitation?",acceptedAnswer:{"@type":"Answer",text:"The MCP spec restricts elicitation's requestedSchema to flat objects with primitive properties only \u2014 strings, numbers, booleans, and enums, no nested objects or arrays of objects. It also explicitly forbids requesting sensitive information through elicitation."}}]},d=[];function u(e){const t={p:"p",strong:"strong",...(0,n.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(o.A,{children:(0,s.jsx)("script",{type:"application/ld+json",children:JSON.stringify(p)})}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.strong,{children:"If your tool server needs to interrupt the model to ask a question, ask why the question wasn't answerable before the call started."})}),"\n",(0,s.jsx)(t.p,{children:"MCP elicitation is a real, spec-defined capability, and it solves a real problem. It's also becoming a convenient place to hide a design problem instead of fixing it."})]})}function h(e={}){const{wrapper:t}={...(0,n.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(u,{...e})}):u(e)}},49363:e=>{e.exports=JSON.parse('{"permalink":"/mcp-elicitation-surfaces-issue-in-your-design","source":"@site/blog/mcp-elicitation-surfaces-issue-in-your-design.mdx","title":"MCP Elicitation Is a Symptom, Not a Strategy","description":"Why reaching for MCP elicitation usually means a tool\'s input contract has a gap; and how atomic, stateless APIs plus HAPI Workflows remove the need for it before it ever reaches the user.","date":"2026-09-15T22:36:03.000Z","tags":[{"inline":false,"label":"MCP","permalink":"/tags/mcp","description":"MCP is an open protocol for connecting LLM apps to external data sources and tools, enabling seamless integration and interoperability.\\n"},{"inline":false,"label":"API-First","permalink":"/tags/api-first","description":"API-First is a design approach that prioritizes the development of APIs before building the actual application, ensuring better integration and scalability.\\n"},{"inline":false,"label":"Architecture","permalink":"/tags/architecture","description":"The structural design and organization of systems, components, and their interactions within a software or hardware environment.\\n"},{"inline":false,"label":"Best Practices","permalink":"/tags/best-practices","description":"Best Practices are established methods or techniques that have been proven to yield optimal results in a particular field or industry.\\n"},{"inline":false,"label":"Arazzo","permalink":"/tags/arazzo","description":"Arazzo defines API workflows\u2014sequences of calls and dependencies\u2014to deliver outcomes using API specs like OpenAPI.\\n"}],"readingTime":11.1,"hasTruncateMarker":true,"authors":[{"name":"Adrian Escutia","title":"La Rebelion Founder","url":"https://adrian.escutia.me","page":{"permalink":"/authors/adrian"},"socials":{"x":"https://x.com/ades_mx","linkedin":"https://www.linkedin.com/in/adrianescutia/","github":"https://github.com/adrianescutia","newsletter":"https://rebelion.la"},"bio":"Adrian is the founder of La Rebelion, a newsletter about AI, technology, and the future. He is also a software engineer and entrepreneur.","imageURL":"https://github.com/adrianescutia.png","key":"adrian"}],"frontMatter":{"title":"MCP Elicitation Is a Symptom, Not a Strategy","description":"Why reaching for MCP elicitation usually means a tool\'s input contract has a gap; and how atomic, stateless APIs plus HAPI Workflows remove the need for it before it ever reaches the user.","authors":["adrian"],"image":"/img/blog/mcp-elicitation-surfaces-issue-in-your-design.png","tags":["mcp","api-first","architecture","best-practices","arazzo"],"keywords":["mcp elicitation","stateless api design","atomic api design","hapi workflows","arazzo","tool server design","mcp best practices"]},"unlisted":false,"prevItem":{"title":"AI Made Code Cheap. Ownership Is Still Expensive.","permalink":"/mcp-multiplication-tax"},"nextItem":{"title":"Do Not Rebuild a Reliable Platform for AI: How Milano Software Is Accelerating AI Adoption","permalink":"/milano-software-hapi-mcp-ai-adoption"}}')}}]);